    15	extern int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size)
    16	{
    17	    if (size == 0) {
    18	        return 0;
    19	    }
    20	    uint8_t decider = data[0];
    21	    size -= 1;
    22	    data += 1;
    23	
    24	    char filename[256];
    25	    sprintf(filename, "/tmp/libfuzzer.%d", getpid());
    26	
    27	    FILE *fp = fopen(filename, "wb");
    28	    if (!fp) {
    29	        return 0;
    30	    }
    31	    fwrite(data, size, 1, fp);
    32	    fclose(fp);
    33	
    34	    if (decider % 1 == 0) {
    35	      H5Fopen(filename, H5F_ACC_RDONLY, H5P_DEFAULT);
    36	    }
    37	    else {
    38	      H5Dopen2(filename, "Dataset name", H5P_DEFAULT);
    39	    }
    40	
    41	    return 0;
    42	}
